 55→// InstallHooks installs Cursor hooks in .cursor/hooks.json.
 56→// If force is true, removes existing Entire hooks before installing.
 57→// Returns the number of hooks installed.
 58→// Unknown top-level fields and hook types are preserved on round-trip.
 59→func (c *CursorAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 60→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 61→	if err != nil {
 62→		worktreeRoot = "."
 63→	}
 64→
 65→	hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
 66→
 67→	// Use raw maps to preserve unknown fields on round-trip
 68→	var rawFile map[string]json.RawMessage
 69→	var rawHooks map[string]json.RawMessage
 70→
 71→	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 72→	if readErr == nil {
 73→		if err := json.Unmarshal(existingData, &rawFile); err != nil {
 74→			return 0, fmt.Errorf("failed to parse existing "+HooksFileName+": %w", err)
 75→		}
 76→		if hooksRaw, ok := rawFile["hooks"]; ok {
 77→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 78→				return 0, fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
 79→			}
 80→		}
 81→		if _, ok := rawFile["version"]; !ok {
 82→			rawFile["version"] = json.RawMessage(`1`)
 83→		}
 84→	} else {
 85→		rawFile = map[string]json.RawMessage{
 86→			"version": json.RawMessage(`1`),
 87→		}
 88→	}
 89→
 90→	if rawHooks == nil {
 91→		rawHooks = make(map[string]json.RawMessage)
 92→	}
 93→
 94→	// Parse only the hook types we manage
 95→	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
 96→	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
 97→	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
 98→	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
 99→	parseCursorHookType(rawHooks, "stop", &stop)
100→	parseCursorHookType(rawHooks, "preCompact", &preCompact)
101→	parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
102→	parseCursorHookType(rawHooks, "subagentStop", &subagentStop)
103→
104→	// If force is true, remove all existing Entire hooks first
105→	if force {
106→		sessionStart = removeEntireHooks(sessionStart)
107→		sessionEnd = removeEntireHooks(sessionEnd)
108→		beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
109→		stop = removeEntireHooks(stop)
110→		preCompact = removeEntireHooks(preCompact)
111→		subagentStart = removeEntireHooks(subagentStart)
112→		subagentStop = removeEntireHooks(subagentStop)
113→	}
114→
115→	// Define hook commands
116→	var cmdPrefix string
117→	if localDev {
118→		cmdPrefix = "go run $(git rev-parse --show-toplevel)/cmd/entire/main.go hooks cursor "
119→	} else {
120→		cmdPrefix = "entire hooks cursor "
121→	}
122→
123→	sessionStartCmd := cmdPrefix + HookNameSessionStart
124→	sessionEndCmd := cmdPrefix + HookNameSessionEnd
125→	beforeSubmitPromptCmd := cmdPrefix + HookNameBeforeSubmitPrompt
126→	stopCmd := cmdPrefix + HookNameStop
127→	preCompactCmd := cmdPrefix + HookNamePreCompact
128→	subagentStartCmd := cmdPrefix + HookNameSubagentStart
129→	subagentEndCmd := cmdPrefix + HookNameSubagentStop
130→
131→	count := 0
132→
133→	// Add hooks if they don't exist
134→	if !hookCommandExists(sessionStart, sessionStartCmd) {
135→		sessionStart = append(sessionStart, CursorHookEntry{Command: sessionStartCmd})
136→		count++
137→	}
138→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
139→		sessionEnd = append(sessionEnd, CursorHookEntry{Command: sessionEndCmd})
140→		count++
141→	}
142→	if !hookCommandExists(beforeSubmitPrompt, beforeSubmitPromptCmd) {
143→		beforeSubmitPrompt = append(beforeSubmitPrompt, CursorHookEntry{Command: beforeSubmitPromptCmd})
144→		count++
145→	}
146→	if !hookCommandExists(stop, stopCmd) {
147→		stop = append(stop, CursorHookEntry{Command: stopCmd})
148→		count++
149→	}
150→	if !hookCommandExists(preCompact, preCompactCmd) {
151→		preCompact = append(preCompact, CursorHookEntry{Command: preCompactCmd})
152→		count++
153→	}
154→	if !hookCommandExists(subagentStart, subagentStartCmd) {
155→		subagentStart = append(subagentStart, CursorHookEntry{Command: subagentStartCmd})
156→		count++
157→	}
158→	if !hookCommandExists(subagentStop, subagentEndCmd) {
159→		subagentStop = append(subagentStop, CursorHookEntry{Command: subagentEndCmd})
160→		count++
161→	}
162→
163→	if count == 0 {
164→		return 0, nil
165→	}
166→
167→	// Marshal modified hook types back into rawHooks
168→	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
169→	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
170→	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
171→	marshalCursorHookType(rawHooks, "stop", stop)
172→	marshalCursorHookType(rawHooks, "preCompact", preCompact)
173→	marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
174→	marshalCursorHookType(rawHooks, "subagentStop", subagentStop)
175→
176→	// Marshal hooks and update raw file
177→	hooksJSON, err := json.Marshal(rawHooks)
178→	if err != nil {
179→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
180→	}
181→	rawFile["hooks"] = hooksJSON
182→
183→	// Write to file
184→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
185→		return 0, fmt.Errorf("failed to create .cursor directory: %w", err)
186→	}
187→
188→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
189→	if err != nil {
190→		return 0, fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
191→	}
192→
193→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
194→		return 0, fmt.Errorf("failed to write "+HooksFileName+": %w", err)
195→	}
196→
197→	return count, nil
198→}
