 86→		}
 87→	} else {
 88→		rawSettings = make(map[string]json.RawMessage)
 89→	}
 90→
 91→	if rawHooks == nil {
 92→		rawHooks = make(map[string]json.RawMessage)
 93→	}
 94→	if rawPermissions == nil {
 95→		rawPermissions = make(map[string]json.RawMessage)
 96→	}
 97→
 98→	// Parse only the hook types we need to modify
 99→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
100→	parseHookType(rawHooks, "SessionStart", &sessionStart)
101→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
102→	parseHookType(rawHooks, "Stop", &stop)
103→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
104→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
105→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
106→	parseHookType(rawHooks, "PreCompact", &preCompact)
107→
108→	// If force is true, remove all existing Entire hooks first
109→	if force {
110→		sessionStart = removeEntireHooks(sessionStart)
111→		sessionEnd = removeEntireHooks(sessionEnd)
112→		stop = removeEntireHooks(stop)
113→		userPromptSubmit = removeEntireHooks(userPromptSubmit)
114→		preToolUse = removeEntireHooks(preToolUse)
115→		postToolUse = removeEntireHooks(postToolUse)
116→		preCompact = removeEntireHooks(preCompact)
117→	}
118→
119→	// Define hook commands
120→	var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, preCompactCmd string
121→	localDevPrefix := "go run $(git rev-parse --show-toplevel)/cmd/entire/main.go hooks factoryai-droid "
122→	if localDev {
123→		sessionStartCmd = localDevPrefix + "session-start"
124→		sessionEndCmd = localDevPrefix + "session-end"
125→		stopCmd = localDevPrefix + "stop"
126→		userPromptSubmitCmd = localDevPrefix + "user-prompt-submit"
127→		preTaskCmd = localDevPrefix + "pre-tool-use"
128→		postTaskCmd = localDevPrefix + "post-tool-use"
129→		preCompactCmd = localDevPrefix + "pre-compact"
130→	} else {
131→		sessionStartCmd = "entire hooks factoryai-droid session-start"
132→		sessionEndCmd = "entire hooks factoryai-droid session-end"
133→		stopCmd = "entire hooks factoryai-droid stop"
134→		userPromptSubmitCmd = "entire hooks factoryai-droid user-prompt-submit"
135→		preTaskCmd = "entire hooks factoryai-droid pre-tool-use"
136→		postTaskCmd = "entire hooks factoryai-droid post-tool-use"
137→		preCompactCmd = "entire hooks factoryai-droid pre-compact"
138→	}
139→
140→	count := 0
141→
142→	// Add hooks if they don't exist
143→	if !hookCommandExists(sessionStart, sessionStartCmd) {
144→		sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
145→		count++
146→	}
147→	// Also install user-prompt-submit on SessionStart to ensure TurnStart fires
148→	// even when UserPromptSubmit doesn't (e.g., droid exec mode).
149→	// The user-prompt-submit handler gracefully handles SessionStart's stdin format
150→	// (userPromptSubmitRaw is a superset of sessionInfoRaw; Prompt defaults to "").
151→	if !hookCommandExists(sessionStart, userPromptSubmitCmd) {
152→		sessionStart = addHookToMatcher(sessionStart, "", userPromptSubmitCmd)
153→		count++
154→	}
155→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
156→		sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
157→		count++
158→	}
159→	if !hookCommandExists(stop, stopCmd) {
160→		stop = addHookToMatcher(stop, "", stopCmd)
161→		count++
162→	}
163→	if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
164→		userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
165→		count++
166→	}
167→	if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
168→		preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
169→		count++
170→	}
171→	if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
172→		postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
173→		count++
174→	}
175→	if !hookCommandExists(preCompact, preCompactCmd) {
176→		preCompact = addHookToMatcher(preCompact, "", preCompactCmd)
177→		count++
178→	}
179→
180→	// Add permissions.deny rule if not present
181→	permissionsChanged := false
182→	var denyRules []string
183→	if denyRaw, ok := rawPermissions["deny"]; ok {
184→		if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
185→			return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
186→		}
187→	}
188→	if !slices.Contains(denyRules, metadataDenyRule) {
189→		denyRules = append(denyRules, metadataDenyRule)
190→		denyJSON, err := json.Marshal(denyRules)
191→		if err != nil {
192→			return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
193→		}
194→		rawPermissions["deny"] = denyJSON
195→		permissionsChanged = true
196→	}
197→
198→	if count == 0 && !permissionsChanged {
199→		return 0, nil // All hooks and permissions already installed
200→	}
201→
202→	// Marshal modified hook types back to rawHooks
203→	marshalHookType(rawHooks, "SessionStart", sessionStart)
204→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
205→	marshalHookType(rawHooks, "Stop", stop)
206→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
207→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
208→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
209→	marshalHookType(rawHooks, "PreCompact", preCompact)
210→
211→	// Marshal hooks and update raw settings
212→	hooksJSON, err := json.Marshal(rawHooks)
213→	if err != nil {
214→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
215→	}
216→	rawSettings["hooks"] = hooksJSON
217→
218→	// Marshal permissions and update raw settings
219→	permJSON, err := json.Marshal(rawPermissions)
220→	if err != nil {
221→		return 0, fmt.Errorf("failed to marshal permissions: %w", err)
222→	}
223→	rawSettings["permissions"] = permJSON
224→
225→	// Write back to file
226→	if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
227→		return 0, fmt.Errorf("failed to create .factory directory: %w", err)
228→	}
229→
230→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
231→	if err != nil {
232→		return 0, fmt.Errorf("failed to marshal settings: %w", err)
233→	}
234→
235→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
236→		return 0, fmt.Errorf("failed to write settings.json: %w", err)
237→	}
238→
239→	return count, nil
240→}
