242→// parseHookType parses a specific hook type from rawHooks into the target slice.
243→// Silently ignores parse errors (leaves target unchanged).
244→func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]FactoryHookMatcher) {
245→	if data, ok := rawHooks[hookType]; ok {
246→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
247→		json.Unmarshal(data, target)
248→	}
249→}
