251→// marshalHookType marshals a hook type back to rawHooks.
252→// If the slice is empty, removes the key from rawHooks.
253→func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []FactoryHookMatcher) {
254→	if len(matchers) == 0 {
255→		delete(rawHooks, hookType)
256→		return
257→	}
258→	data, err := json.Marshal(matchers)
259→	if err != nil {
260→		return // Silently ignore marshal errors (shouldn't happen)
261→	}
262→	rawHooks[hookType] = data
263→}
