387→// AreHooksInstalled checks if Entire hooks are installed.
388→func (f *FactoryAIDroidAgent) AreHooksInstalled(ctx context.Context) bool {
389→	// Use repo root to find .factory directory when run from a subdirectory
390→	repoRoot, err := paths.WorktreeRoot(ctx)
391→	if err != nil {
392→		repoRoot = "." // Fallback to CWD if not in a git repo
393→	}
394→	settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
395→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
396→	if err != nil {
397→		return false
398→	}
399→
400→	var settings FactorySettings
401→	if err := json.Unmarshal(data, &settings); err != nil {
402→		return false
403→	}
404→
405→	// Check for at least one of our hooks (production or local-dev format)
406→	return hookCommandExists(settings.Hooks.Stop, "entire hooks factoryai-droid stop") ||
407→		hookCommandExists(settings.Hooks.Stop, "go run $(git rev-parse --show-toplevel)/cmd/entire/main.go hooks factoryai-droid stop")
